import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Built-in Memory Provider","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/providers/memory/builtin.md","filePath":"integrations/providers/memory/builtin.md","lastUpdated":1788855895000}'),o={name:"integrations/providers/memory/builtin.md"};function n(s,e,d,l,h,p){return i(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="built-in-memory-provider" tabindex="-1">Built-in Memory Provider <a class="header-anchor" href="#built-in-memory-provider" aria-label="Permalink to &quot;Built-in Memory Provider&quot;">​</a></h1><p>The built-in memory provider is the standard memory backend shipped with Memoh. It works with Memoh&#39;s memory pipeline and supports:</p><ul><li>Automatic memory extraction from conversations</li><li>Semantic memory retrieval during chat</li><li>Manual memory creation and editing</li><li>Memory compaction and rebuild workflows</li></ul><hr><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>The built-in provider runs in <strong>graph</strong> mode. Memory nodes and edges are stored in PostgreSQL as the source of truth, and a Markdown view (the <code>memory/</code> bundle plus <code>MEMORY.md</code> in the bot workspace) is derived from them for the agent to read and edit.</p><p>Semantic retrieval is optional and layered on top:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Storage</th><th>Requirements</th><th>What it adds</th></tr></thead><tbody><tr><td><strong>Graph</strong> (always on)</td><td>PostgreSQL memory nodes/edges</td><td>None beyond the main database</td><td>Structured recall, relations between memories, compaction, rebuild</td></tr><tr><td><strong>Semantic index</strong> (optional)</td><td><code>pgvector</code> database</td><td>The <code>[pgvector]</code> database from the Compose stack <strong>and</strong> an embedding model selected on the provider</td><td>Vector similarity search over memory nodes</td></tr></tbody></table><p>If no embedding model is set, or the <code>pgvector</code> database is not configured, the provider still works in graph-only mode; semantic search is simply skipped.</p><hr><h2 id="creating-a-built-in-provider" tabindex="-1">Creating a Built-in Provider <a class="header-anchor" href="#creating-a-built-in-provider" aria-label="Permalink to &quot;Creating a Built-in Provider&quot;">​</a></h2><ol><li>Navigate to the <strong>Memory Providers</strong> page.</li><li>Click <strong>Add Memory Provider</strong>.</li><li>Fill in the following fields: <ul><li><strong>Name</strong>: A display name for this provider.</li><li><strong>Provider Type</strong>: Select <code>builtin</code>.</li></ul></li><li>Click <strong>Create</strong>.</li></ol><hr><h2 id="configuring-a-built-in-provider" tabindex="-1">Configuring a Built-in Provider <a class="header-anchor" href="#configuring-a-built-in-provider" aria-label="Permalink to &quot;Configuring a Built-in Provider&quot;">​</a></h2><p>After creating a provider, select it from the list and configure its settings.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Embedding Model</strong></td><td>Optional. An embedding model from one of your LLM providers. When set (and <code>pgvector</code> is available), memory nodes are embedded and semantic search is enabled. Leave empty for graph-only mode.</td></tr></tbody></table><h3 id="managing-providers" tabindex="-1">Managing Providers <a class="header-anchor" href="#managing-providers" aria-label="Permalink to &quot;Managing Providers&quot;">​</a></h3><ul><li><strong>Edit</strong>: Select a provider and update its settings.</li><li><strong>Delete</strong>: Remove a provider you no longer use.</li></ul><hr><h2 id="infrastructure-requirements" tabindex="-1">Infrastructure Requirements <a class="header-anchor" href="#infrastructure-requirements" aria-label="Permalink to &quot;Infrastructure Requirements&quot;">​</a></h2><h3 id="graph-only" tabindex="-1">Graph-only <a class="header-anchor" href="#graph-only" aria-label="Permalink to &quot;Graph-only&quot;">​</a></h3><p>No additional infrastructure beyond the main PostgreSQL database.</p><h3 id="semantic-index" tabindex="-1">Semantic index <a class="header-anchor" href="#semantic-index" aria-label="Permalink to &quot;Semantic index&quot;">​</a></h3><p>The default Docker Compose stack already includes a <code>pgvector</code> service and the matching section in <code>config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgvector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pgvector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh_vector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sslmode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;disable&quot;</span></span></code></pre></div><p>Then pick an <strong>Embedding Model</strong> on the provider. Embeddings are generated through the selected LLM provider (OpenAI, Gemini, Ollama, ...), so that provider must expose an embedding-capable model.</p><hr><h2 id="assigning-a-memory-provider-to-a-bot" tabindex="-1">Assigning a Memory Provider to a Bot <a class="header-anchor" href="#assigning-a-memory-provider-to-a-bot" aria-label="Permalink to &quot;Assigning a Memory Provider to a Bot&quot;">​</a></h2><ol><li>Navigate to the <strong>Bots</strong> page and open your bot.</li><li>Go to the <strong>General</strong> tab.</li><li>Find the <strong>Memory Provider</strong> dropdown.</li><li>Select the provider you created.</li><li>Click <strong>Save</strong>.</li></ol><p>If no memory provider is selected, the bot will not use that provider configuration in its runtime settings.</p><hr><h2 id="using-memory-after-setup" tabindex="-1">Using Memory After Setup <a class="header-anchor" href="#using-memory-after-setup" aria-label="Permalink to &quot;Using Memory After Setup&quot;">​</a></h2><p>Once a memory provider is assigned to the bot, you can manage actual memories from the bot&#39;s <strong>Memory</strong> tab:</p><ul><li>Create memories manually</li><li>Extract memories from conversations</li><li>Search, edit, and delete memories</li><li>Compact or rebuild the memory store</li></ul><p>For day-to-day memory operations, continue with <a href="/guides/memory.html">Bot Memory Management</a>.</p>`,35)])])}const g=t(o,[["render",n]]);export{c as __pageData,g as default};
